import os

import gi
gi.require_version('Gtk', '3.0')
from gi.repository import Gdk, GLib

import logging
logger = logging.getLogger(__name__)

from mvc.adapters.gtk_support.treemodels.utils import create_treestore_from_directory

from mudlab.data import settings

from mudlab.generic.views.combobox_tools import add_combo_text_column
from mudlab.generic.controllers import DialogController

from mudlab.probabilities.models import get_Gbounds_for_R, get_Rbounds_for_G

class AddPhaseController(DialogController):
    """
        Controller for the add phase dialog
    """

    auto_adapt = False

    def __init__(self, model=None, view=None, parent=None, callback=None):
        super(AddPhaseController, self).__init__(
            model=model, view=view, parent=parent)
        self.callback = callback

    def register_view(self, view):
        self.update_bounds()
        self.generate_combo()

    def register_adapters(self):
        pass # has no intel, or a model!

    def update_R_bounds(self):
        if self.view is not None:
            min_R, max_R, R = get_Rbounds_for_G(
                self.view.get_G(), self.view.get_R())
            self.view["adj_R"].set_upper(max_R)
            self.view["adj_R"].set_lower(min_R)
            self.view["R"].set_value(R)

    def update_G_bounds(self):
        if self.view is not None:
            min_G, max_G, G = get_Gbounds_for_R(
                self.view.get_R(), self.view.get_G())
            self.view["adj_G"].set_upper(max_G)
            self.view["adj_G"].set_lower(min_G)
            self.view["G"].set_value(G)

    def update_bounds(self):
        self.update_G_bounds()
        self.update_R_bounds()

    def generate_combo(self):
        self.reload_combo_model()
        add_combo_text_column(
            self.view.phase_combo_box, text_col=0, sensitive_col=2)

    def reload_combo_model(self):
        cmb_model = create_treestore_from_directory(
            settings.DATA_REG.get_directory_path("DEFAULT_PHASES"))
        self.view.phase_combo_box.set_model(cmb_model)

    # ------------------------------------------------------------
    #      GTK Signal handlers
    # ------------------------------------------------------------
    def on_btn_ok_clicked(self, event):
        self.view.hide()
        self.callback(
            self.view.get_phase_type(), self.view.get_G(), self.view.get_R())
        return True

    def on_rdb_toggled(self, widget):
        self.view.update_sensitivities()
        # Auto-generate default phases on first selection of "Choose a default phase"
        # Only act on the widget becoming active (toggled fires for both radios)
        if widget.get_active() and self.view.active_type == "default":
            phases_dir = settings.DATA_REG.get_directory_path("DEFAULT_PHASES")
            has_phases = (os.path.isdir(phases_dir) and len(os.listdir(phases_dir)) > 0)
            if not has_phases:
                GLib.idle_add(self._auto_generate_phases)

    def _run_phase_generation(self):
        """Run phase generation with progress feedback. Disables the dialog
        to prevent user interaction that could cause crashes."""
        from mudlab.scripts.generate_default_phases import run

        # Disable the entire dialog content to prevent interaction during generation
        toplevel = self.view.get_toplevel()
        toplevel.set_sensitive(False)

        def ui_callback(progress):
            self.view["gen_progress_bar"].set_fraction(progress)
            GLib.MainContext.default().iteration(False)

        self.view["img_repeat"].set_visible(False)
        self.view["gen_spinner"].start()
        self.view["gen_spinner"].set_visible(True)
        self.view["gen_progress_bar"].set_visible(True)
        GLib.MainContext.default().iteration(False)
        run(ui_callback=ui_callback)
        self.view["gen_progress_bar"].set_visible(False)
        self.view["img_repeat"].set_visible(True)
        self.view["gen_spinner"].stop()
        self.view["gen_spinner"].set_visible(False)
        self.reload_combo_model()

        # Re-enable the dialog
        toplevel.set_sensitive(True)

    def _auto_generate_phases(self):
        """Called via GLib.idle_add on first run when no default phases exist.
        Shows a confirmation dialog before starting generation."""
        import gi
        gi.require_version('Gtk', '3.0')
        from gi.repository import Gtk

        dialog = Gtk.MessageDialog(
            transient_for=self.view.get_toplevel(),
            modal=True,
            message_type=Gtk.MessageType.INFO,
            buttons=Gtk.ButtonsType.OK_CANCEL,
            text="Generating default phases",
        )
        dialog.format_secondary_text(
            "Default phases need to be generated for first use. "
            "This will take a while.\n\n"
            "Press OK to start now, or Cancel to do it later "
            "using the regenerate button."
        )
        response = dialog.run()
        dialog.destroy()

        if response == Gtk.ResponseType.OK:
            self._run_phase_generation()
        else:
            # Revert to "Create a new phase" so the empty combo isn't shown
            self.view["rdb_empty_phase"].set_active(True)
            self.view.update_sensitivities()

        return False  # don't repeat the idle call

    def on_btn_generate_phases_clicked(self, event):
        self._run_phase_generation()
        return True

    def on_r_value_changed(self, *args):
        self.update_G_bounds()
        return True

    def on_g_value_changed(self, *args):
        self.update_R_bounds()
        return True

    def on_keypress(self, widget, event):
        if event.keyval == Gdk.keyval_from_name("Escape"):
            self.view.hide()
            return True
        if event.keyval == Gdk.keyval_from_name("Enter"):
            self.view.hide()
            self.callback(
                self.view.get_phase_type(), self.view.get_G(), self.view.get_R())
            return True

    def on_window_edit_dialog_delete_event(self, event, args=None):
        self.view.hide()
        return True # do not propagate

    pass # end of class